INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26801, 'Romans 1:4', 'Romans', 1, 4, '&nbsp;خو د روحُ القُدس په قدرت سره هغه د مړو نه بيا راژوندے شو، په دې وجه هغه د خُدائ پاک زوئ وبللے شو، يعنې زمونږ مالِک عيسىٰ مسيح.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26802, 'Romans 1:5', 'Romans', 1, 5, '&nbsp;د هغۀ په وسيله مونږ ته دا فضل او رسالت بخښلے شوے دے چې د هغۀ د نوم دپاره ټولو غېرو قومونو ته بلنه ورکړُو چې د ايمان په وسيله تابعدارى وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26803, 'Romans 1:6', 'Romans', 1, 6, '&nbsp;او تاسو هم په هغه رابللے شوو خلقو کښې شامل يئ چې د عيسىٰ مسيح سره تړون ولرئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26804, 'Romans 1:7', 'Romans', 1, 7, '&nbsp;زۀ د روم هغه ټولو اوسېدونکو ته سلام وايم چې د خُدائ پاک محبوبان دى او چې د ايماندار کېدو دپاره رابللے شوى دى. زمونږ خُدائ پلار او مالِک عيسىٰ مسيح دې تاسو لا فضل او سلامتى درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26805, 'Romans 1:8', 'Romans', 1, 8, '&nbsp;د ټولو نه اول زۀ د عيسىٰ مسيح په نوم ستاسو دپاره د خپل خُدائ پاک شُکر ادا کوم ځکه چې په ټوله دُنيا کښې ستاسو د ايمان خبرې کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26806, 'Romans 1:9', 'Romans', 1, 9, '&nbsp;هغه خُدائ پاک د چا چې زۀ د خپل زړۀ نه خِدمت کوم او د هغۀ د زوئ زيرے خوروم، هغه خُدائ پاک زما ګواه دے چې زۀ تاسو مسلسل په خپلو دُعاګانو کښې يادوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26807, 'Romans 1:10', 'Romans', 1, 10, '&nbsp;او همېشه دا سوال کوم چې د خُدائ پاک په مرضۍ دې آخر هم زۀ د دې جوګه شم چې تاسو ووينم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26808, 'Romans 1:11', 'Romans', 1, 11, '&nbsp;زۀ ستاسو د ليدو خواهشمند يم او دا غواړم چې تاسو ته څۀ روحانى نعمت درکړم چې تاسو پرې قوى او مضبوط شئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26809, 'Romans 1:12', 'Romans', 1, 12, '&nbsp;هغه دا چې په خپلو کښې به يو بل ته په ايمان کښې ډاډ ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26810, 'Romans 1:13', 'Romans', 1, 13, '&nbsp;اے زما وروڼو او خوېندو، زۀ غواړم چې تاسو په دې پوهه شئ چې ما ډېر ځله تاسو ته د راتلو کوشش کړے دے خو تر اوسه پورې د دې نه منع کړے شوے يم. او زۀ په دې طمع ناست يم چې په تاسو کښې کار وکړم او تاسو د ايمان ملګرى جوړ کړم، لکه څنګه چې مې په نورو غېرو يهوديانو کښې جوړ کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26811, 'Romans 1:14', 'Romans', 1, 14, '&nbsp;زۀ د مهذب او د غېر مهذب خلقو، د عالمانو او د عاميانو، د ټولو احسان مند يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26812, 'Romans 1:15', 'Romans', 1, 15, '&nbsp;ځکه زۀ دا غواړم چې تاسو ته چې په روم کښې يئ، زيرے درورسوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26813, 'Romans 1:16', 'Romans', 1, 16, '&nbsp;زۀ د مسيح د زيرى نه نۀ شرمېږم، ځکه چې د هر چا دپاره چې ايماندار وى دا د خلاصون دپاره د خُدائ پاک قدرت دے، اول د يهوديانو دپاره، بيا د غېر‌يهوديانو دپاره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26814, 'Romans 1:17', 'Romans', 1, 17, '&nbsp;ځکه چې هم د دې نه د خُدائ پاک هغه صداقت څرګنديږى چې د ايمان نه شروع کيږى او په ايمان تر سره کيږى، لکه چې صحيفې وائى، ”څوک چې صادق وى هغه به په ايمان پائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26815, 'Romans 1:18', 'Romans', 1, 18, '&nbsp;خو د خُدائ پاک غضب د آسمان نه په هغه ټولو بې‌دينه او بدکارو خلقو نازليږى، څوک چې حقيقت په خپل منافقت سره پټوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26816, 'Romans 1:19', 'Romans', 1, 19, '&nbsp;او هغوئ د خُدائ پاک په حقله د حقيقت نه خبر دى، ځکه چې خُدائ پاک په خپله هغه هغوئ ته ښکاره کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26817, 'Romans 1:20', 'Romans', 1, 20, '&nbsp;د کله نه چې خُدائ پاک دا دُنيا پېدا کړې ده د هغۀ پټ صِفتونه لکه د هغه دائمى او الاهى قوت په هغه ټولو څيزونو کښې ښکارى کوم چې هغۀ پېدا کړى دى. نو ځکه د چا سره هم د خُدائ پاک د نۀ پېژندلو په حقله هيڅ عُذر نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26818, 'Romans 1:21', 'Romans', 1, 21, '&nbsp;اګر کۀ هغوئ خُدائ پاک پېژندلو، خو بيا هم د خُدائ پاک د احترام کولو نه يې اِنکار کولو او ناشُکره وُو، بلکې د هغوئ ټول خيالات باطل شول او د هغوئ بې‌احساسه زړونه په تيارۀ کښې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26819, 'Romans 1:22', 'Romans', 1, 22, '&nbsp;هغوئ د هوښيارتيا دعوىٰ کوله خو هغوئ بې‌عقله وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26820, 'Romans 1:23', 'Romans', 1, 23, '&nbsp;او هغوئ د ابدى او لوئ خُدائ پاک په ځائ د فانى انسان، د مارغانو، د ځناورو او مارانو په شکل څيزونو عبادت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26821, 'Romans 1:24', 'Romans', 1, 24, '&nbsp;هم په دې وجه خُدائ پاک هغوئ د خپل نفس ناپاکه خواهشاتو ته پرېښودل، او آخر دا چې هغوئ په خپلو کښې ځانونه يو تر بله وشرمول،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26822, 'Romans 1:25', 'Romans', 1, 25, '&nbsp;ځکه چې هغوئ د خُدائ پاک حقيقت په دروغو بدل کړو او د مخلوق عبادت او خِدمت يې د هغه خالِق په ځائ وکړو، څوک چې تل تر تله د حمد لائق دے، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26823, 'Romans 1:26', 'Romans', 1, 26, '&nbsp;نو ځکه خُدائ پاک هغوئ بې‌شرمه شهوتونو ته پرېښودل. د هغوئ ښځو د فطرى جنسى عمل په ځائ غېر فطرى جنسى عمل خپل کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26824, 'Romans 1:27', 'Romans', 1, 27, '&nbsp;او د هغوئ سړو هم دغه شان د ښځو سره د فطرى جنسى عمل په ځائ د يو بل سره بدکارى راواخسته او سړو د سړو سره شرمناک کارونه وکړل، او اَنجام يې دا چې په خپله يې د دې ګمراهۍ بدله او سزا وموندله', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26825, 'Romans 1:28', 'Romans', 1, 28, '&nbsp;او څنګه چې هغوئ د خُدائ پاک پېژندل خوښ نۀ کړل نو خُدائ پاک هم هغوئ خپلو باطلو خيالاتو ته پرېښودل چې په هم دې بدعملۍ آخته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26826, 'Romans 1:29', 'Romans', 1, 29, '&nbsp;هغوئ د هر قِسم بې‌اِنصافۍ، بدۍ، لالچ او بدو خواهشاتو نه ډک شول. او هغوئ د حسد، قتل، جګړې، ټګۍ او بُغض نه ډک دى. پشى شا خبرې کوونکى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26827, 'Romans 1:30', 'Romans', 1, 30, '&nbsp;غېبت کوونکى، د خُدائ پاک نه نفرت کوونکى، بد سره، مغروره او لافې کوونکى دى. دوئ ورانے جوړوى او د مور پلار نافرمانه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26828, 'Romans 1:31', 'Romans', 1, 31, '&nbsp;دوئ کم عقل، بې‌ايمانه، بې‌رحمه، ظلم کوونکى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26829, 'Romans 1:32', 'Romans', 1, 32, '&nbsp;د خُدائ پاک په دې فرمان هغوئ ښۀ خبر دى چې هغه څوک چې داسې عمل کوى، هغوئ د مرګ لائق دى خو بيا هم هغوئ داسې کوى. هغوئ نۀ صرف دا کوى بلکې داسې کوونکو ته شاباسے هم ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26830, 'Romans 2:1', 'Romans', 2, 1, '&nbsp;اے دوستانو، تاسو چې بل څوک مجرموئ، تاسو هر څوک چې يئ، تاسو سره هيڅ عُذر نشته. کله چې تاسو بل څوک مجرموئ نو په دې سره تاسو خپل ځان مجرموئ ځکه چې هم هغه کارونه تاسو په خپله کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26831, 'Romans 2:2', 'Romans', 2, 2, '&nbsp;اوس مونږ ته پته ده څوک چې داسې کارونه کوى نو خُدائ پاک په اِنصاف سره د هغوئ عدالت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26832, 'Romans 2:3', 'Romans', 2, 3, '&nbsp;نو کله چې تاسو نور په داسې کارونو مجرموئ، او بيا تاسو په خپله هم هغه کارونه کوئ نو ولې تاسو دا سوچ کوئ چې ګنې تاسو به د خُدائ پاک د عدالت نه بچ شئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26833, 'Romans 2:4', 'Romans', 2, 4, '&nbsp;او يا دا چې تۀ د هغۀ د لوئې مهربانۍ، د زغم، او د صبر پېمانه سپکه ګڼې څۀ؟ ولې تاسو په دې نۀ پوهېږئ چې د خُدائ پاک د مهربانۍ وجه دا ده چې تاسو توبه وباسئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26834, 'Romans 2:5', 'Romans', 2, 5, '&nbsp;بلکې تاسو د خپل سخت او ناتوبه ګاره زړونو په وسيله د خپل ځان دپاره د خُدائ پاک د قهر د ورځې غضب زياتوئ کله چې به د خُدائ رښتونے عدالت شروع شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26835, 'Romans 2:6', 'Romans', 2, 6, '&nbsp;هغه به هر چا ته د هغوئ د کارونو په مطابق اجر ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26836, 'Romans 2:7', 'Romans', 2, 7, '&nbsp;څوک چې په صبر سره ښۀ کوى او د جلال او د عزت او د نۀ ختمېدونکى ژوند لټون کوى، هغوئ ته به خُدائ پاک د تل ژوندون ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26837, 'Romans 2:8', 'Romans', 2, 8, '&nbsp;خو هغوئ څوک چې خود غرضه دى او د حق نه منکر دى او غلط کارونه کوى، په هغوئ به قهر او غضب نازل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26838, 'Romans 2:9', 'Romans', 2, 9, '&nbsp;د هغوئ ټولو دپاره به مصيبت او تکليفونه وى څوک چې بدکاره وى، اول د يهودى او بيا د غېر يهودى دپاره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26839, 'Romans 2:10', 'Romans', 2, 10, '&nbsp;خو د ټولو نېکى کوونکو دپاره جلال او عزت او سلامتى ده، اول د يهودى او بيا د غېر يهودى دپاره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26840, 'Romans 2:11', 'Romans', 2, 11, '&nbsp;ځکه چې خُدائ پاک د چا طرفدارے هم نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26841, 'Romans 2:12', 'Romans', 2, 12, '&nbsp;هغوئ ټولو چا چې د موسىٰ د شريعت نه بغېر ګناه کړې وى، نو هغوئ به د شريعت نه بغېر هلاک شى، او هغوئ ټولو چا چې د شريعت د لاندې ګناه کړې وى، هغوئ به د شريعت د لاندې سزا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26842, 'Romans 2:13', 'Romans', 2, 13, '&nbsp;ځکه چې نۀ صرف د شريعت په اورېدو بلکې په هغې د عمل کولو په وسيله سړے د خُدائ پاک په نظر کښې صادق کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26843, 'Romans 2:14', 'Romans', 2, 14, '&nbsp;هغه غېر‌يهوديان چې د شريعت نه ناخبره وى او په قدرتى توګه هغه څۀ کوى څۀ چې په شريعت کښې وى، کۀ څۀ هم چې د هغوئ سره شريعت نشته، خو د هغوئ عمل ورته شريعت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26844, 'Romans 2:15', 'Romans', 2, 15, '&nbsp;نو هغوئ دا ښکاره کوى څۀ چې په شريعت کښې دى هغه د هغوئ په زړُونو ليکلى دى. د هغوئ ضمير د هغې ګواهى ورکوى او د هغوئ خيالونه به هغوئ ملامتوى او يا به د هغوئ دفاع کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26845, 'Romans 2:16', 'Romans', 2, 16, '&nbsp;دا هغه زيرے دے چې زۀ يې تاسو ته اوروم، هغه ورځ راتلونکى ده چې خُدائ پاک به د عيسىٰ مسيح په وسيله د خلقو د پټو خيالونو عدالت وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26846, 'Romans 2:17', 'Romans', 2, 17, '&nbsp;خو کۀ تاسو ځان ته يهوديان وايئ او په شريعت ټينګ ولاړ يئ او خُدائ پاک سره په خپل تعلق فخر کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26847, 'Romans 2:18', 'Romans', 2, 18, '&nbsp;او تاسو ته د هغۀ رضا معلومه ده او د ښو او بدو نه خبر يئ، دا ځکه چې تاسو ته په شريعت کښې دا تعليم درکړے شوے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26848, 'Romans 2:19', 'Romans', 2, 19, '&nbsp;او ستاسو په دې يقين دے چې تاسو د ړندو لارښودونکى يئ او د هغوئ دپاره رڼا يئ څوک چې په تيارۀ کښې دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
