(26896, 'Romans 4:7', 'Romans', 4, 7, '&nbsp;”بختور دى هغوئ د چا نافرمانى چې معاف شوه، او د چا په ګناهونو چې پړده واچولے شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26897, 'Romans 4:8', 'Romans', 4, 8, '&nbsp;بختور هغه کس دے د چا بد چې مالِک خُدائ حساب نۀ کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26898, 'Romans 4:9', 'Romans', 4, 9, '&nbsp;ولې دا خوشحالى تش د سنت شوو دپاره ده، يا دا د ناسنتو دپاره هم ده؟ مونږ وايو چې، ”د اِبراهيم ايمان په صداقت حساب شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26899, 'Romans 4:10', 'Romans', 4, 10, '&nbsp;نو هغۀ ته دا څنګه حساب کړے شو؟ ولې هغه په هغه وخت کښې سنت وو کۀ نه؟ نه، هغه ناسنته وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26900, 'Romans 4:11', 'Romans', 4, 11, '&nbsp;هغۀ ته د سنت نښه د صداقت د مهر په طور مِلاو شوه کومه چې هغۀ د ايمان په وسيله حاصله کړه ځکه چې هغه لا ناسنته وو. د دې مطلب دا وو چې هغه د هغوئ ټولو هم نيکۀ شى چا چې بغېر د سنت کېدو نه ايمان راوړو او هم په دې وجه هغوئ صادق وګڼلے شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');